// Real-data bit-exact check of idct_butterfly.h's IDCT (spec-bink-codec.md
// Sec5.3j Part 1) against spec-bink-video-test-vectors.md's own
// independently-FFmpeg-verified post-IDCT block
// (postidct_block_frame0_row0_col80_VERIFIED.bin) and the real DC/AC
// coefficient struct that feeds it (dc_ac_coeffs_frame0_block0.bin).
//
// Both fixtures are gitignored/local-only (tests/golden/bink_main_menu_bg/
// vectors/), regenerated by tools/bink_test_vector_extract.cpp off the
// committed spec-bink-video-test-vectors.md file - SKIPPED (exit 77) if
// absent, same convention as every other real_bink_*_test.
//
// This is the SAME 64-coefficient struct/64-pixel block Sec5.3j's own
// "Bit-exact verification" paragraph cites (quantizer nibble 6, DC=51, AC
// nonzero at k=1,2,8,9,10,17: -3,-1,-3,1,1,1) - this test is this project's
// own independent re-confirmation that idctBlock8x8() reproduces that exact
// result, not a restatement of the spec's own claim.

#include <cstdint>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

#include "sr3binkcodec/entropy_prestage_tables.h"
#include "sr3binkcodec/idct_butterfly.h"
#include "bink_sha256.h"

#ifndef BINK_MMBG_GOLDEN_DIR
#define BINK_MMBG_GOLDEN_DIR "tests/golden/bink_main_menu_bg"
#endif

using namespace sr3binkcodec;

namespace {
int g_failures = 0;
#define CHECK(cond)                                                                           \
    do {                                                                                      \
        if (!(cond)) {                                                                        \
            std::cerr << "CHECK FAILED: " #cond " at " << __FILE__ << ":" << __LINE__ << "\n"; \
            ++g_failures;                                                                      \
        }                                                                                      \
    } while (0)

std::vector<uint8_t> readFile(const std::string& path) {
    std::ifstream f(path, std::ios::binary | std::ios::ate);
    if (!f) return {};
    std::streamsize n = f.tellg();
    if (n <= 0) return {};
    f.seekg(0);
    std::vector<uint8_t> buf(static_cast<size_t>(n));
    f.read(reinterpret_cast<char*>(buf.data()), n);
    if (!f) return {};
    return buf;
}

std::vector<uint8_t> loadVerified(const std::string& path, size_t expectedSize, const std::string& expectedSha,
                                   const std::string& label, bool& ok) {
    std::vector<uint8_t> data = readFile(path);
    if (data.empty()) {
        std::cout << "  MISSING: " << label << " ('" << path << "')\n";
        ok = false;
        return {};
    }
    const std::string actualSha = bink_test_sha256::computeSha256Hex(data.data(), data.size());
    if (data.size() != expectedSize || actualSha != expectedSha) {
        std::cout << "  HASH MISMATCH: " << label << "\n";
        ok = false;
        return {};
    }
    std::cout << "  OK: " << label << " (" << data.size() << " bytes)\n";
    return data;
}

}  // namespace

int main() {
    std::cout << "real_bink_idct_test: idct_butterfly.h vs. the real FFmpeg-verified post-IDCT block\n";
    bool allOk = true;
    const std::vector<uint8_t> coeffsRaw =
        loadVerified(std::string(BINK_MMBG_GOLDEN_DIR) + "/vectors/dc_ac_coeffs_frame0_block0.bin", 256,
                     "1ab4ff8584beeb0bd8c09040f4acfc299a767a5dc829a5a85d0318d63abc76c0",
                     "dc_ac_coeffs_frame0_block0.bin", allOk);
    const std::vector<uint8_t> expectedPixels =
        loadVerified(std::string(BINK_MMBG_GOLDEN_DIR) + "/vectors/postidct_block_frame0_row0_col80_VERIFIED.bin", 64,
                     "51033a4c25b21922d31789e495da699b7301af4090fa7d1f99f63179b45ead78",
                     "postidct_block_frame0_row0_col80_VERIFIED.bin", allOk);
    if (!allOk) {
        std::cout << "real_bink_idct_test: SKIPPED (fixture(s) missing/mismatched - regenerate via "
                     "tools/bink_test_vector_extract.cpp against spec-bink-video-test-vectors.md)\n";
        return 77;
    }

    // First 64 int16 words of the 256-byte struct, row-major
    // struct_byte_offset(k)=2k (spec-bink-codec.md Sec5.3b, re-confirmed by
    // this file's own k=1/k=2/k=8/k=9/k=10/k=17 values matching Sec5.3j's
    // own cited worked example exactly: DC=51, AC -3,-1 at k=1/2, -3,1,1 at
    // k=8/9/10, 1 at k=17).
    int16_t coeffs[64];
    for (int k = 0; k < 64; ++k) {
        coeffs[k] = static_cast<int16_t>(static_cast<uint16_t>(coeffsRaw[static_cast<size_t>(k) * 2]) |
                                          (static_cast<uint16_t>(coeffsRaw[static_cast<size_t>(k) * 2 + 1]) << 8));
    }
    CHECK(coeffs[0] == 51);
    CHECK(coeffs[1] == -3);
    CHECK(coeffs[2] == -1);
    CHECK(coeffs[8] == -3);
    CHECK(coeffs[9] == 1);
    CHECK(coeffs[10] == 1);
    CHECK(coeffs[17] == 1);

    // Quantizer nibble 6 (Sec5.3j: "quantizer nibble 6 (edx-0x10037cc0 =
    // 0x600 = 6*256)"), intra table (this block is frame 0, intra-only).
    constexpr uint32_t kQuantNibble = 6;
    int32_t quantRow[64];
    for (int k = 0; k < 64; ++k) {
        const size_t off = static_cast<size_t>(kQuantNibble) * 256 + static_cast<size_t>(k) * 4;
        uint32_t v = static_cast<uint32_t>(kIntraQuantCompiled[off]) |
                     (static_cast<uint32_t>(kIntraQuantCompiled[off + 1]) << 8) |
                     (static_cast<uint32_t>(kIntraQuantCompiled[off + 2]) << 16) |
                     (static_cast<uint32_t>(kIntraQuantCompiled[off + 3]) << 24);
        quantRow[k] = static_cast<int32_t>(v);
    }

    uint8_t pixels[64];
    idctBlock8x8(coeffs, quantRow, pixels);

    bool allMatch = true;
    for (int i = 0; i < 64; ++i) {
        if (pixels[i] != expectedPixels[static_cast<size_t>(i)]) {
            allMatch = false;
            std::cout << "  MISMATCH at pixel " << i << ": got 0x" << std::hex << static_cast<int>(pixels[i])
                       << " expected 0x" << static_cast<int>(expectedPixels[static_cast<size_t>(i)]) << std::dec
                       << "\n";
        }
    }
    CHECK(allMatch);
    std::cout << "idct_butterfly.h result vs. real FFmpeg-verified ground truth: "
              << (allMatch ? "BIT-EXACT MATCH, all 64 bytes" : "MISMATCH - see above") << "\n";

    if (g_failures != 0) {
        std::cerr << g_failures << " check(s) failed\n";
        return 1;
    }
    std::cout << "real_bink_idct_test: all checks passed\n";
    return 0;
}
